with open('eval.scm', 'r') as f:
    content = f.read()

depth = 0
in_comment = False
for i, ch in enumerate(content):
    if ch == ';':
        in_comment = True
    elif ch == '\n':
        in_comment = False
    elif ch == '(' and not in_comment:
        depth += 1
    elif ch == ')' and not in_comment:
        depth -= 1
        if depth < 0:
            print(f"Extra ) at position {i}, char: {repr(content[i-20:i+20])}")
            depth = 0

print(f"Final depth: {depth}")
